/**
 * Subtitle Format Converter
 * Convert between SRT, VTT, ASS, SSA, SUB formats
 */

class SubtitleConverter {
  constructor() {
    this.supportedFormats = ['srt', 'vtt', 'ass', 'ssa', 'sub'];
  }

  /**
   * Convert subtitles to specified format
   */
  convert(subtitles, targetFormat) {
    targetFormat = targetFormat.toLowerCase();

    if (!this.supportedFormats.includes(targetFormat)) {
      throw new Error(`Unsupported target format: ${targetFormat}`);
    }

    logInfo('Converting subtitles', { 
      count: subtitles.length,
      to: targetFormat 
    });

    let output = '';

    switch (targetFormat) {
      case 'srt':
        output = this.toSRT(subtitles);
        break;
      case 'vtt':
        output = this.toVTT(subtitles);
        break;
      case 'ass':
        output = this.toASS(subtitles);
        break;
      case 'ssa':
        output = this.toSSA(subtitles);
        break;
      case 'sub':
        output = this.toSUB(subtitles);
        break;
    }

    return output;
  }

  /**
   * Convert to SRT format
   */
  toSRT(subtitles) {
    return subtitles.map((sub, idx) => {
      const index = idx + 1;
      const startTime = this.formatSRTTimestamp(sub.startTime);
      const endTime = this.formatSRTTimestamp(sub.endTime);
      const text = sub.text.trim();

      return `${index}\n${startTime} --> ${endTime}\n${text}\n`;
    }).join('\n');
  }

  /**
   * Convert to VTT format
   */
  toVTT(subtitles) {
    let output = 'WEBVTT\n\n';

    output += subtitles.map((sub, idx) => {
      const startTime = this.formatVTTTimestamp(sub.startTime);
      const endTime = this.formatVTTTimestamp(sub.endTime);
      const text = sub.text.trim();

      return `${startTime} --> ${endTime}\n${text}\n`;
    }).join('\n');

    return output;
  }

  /**
   * Convert to ASS format
   */
  toASS(subtitles) {
    let output = '';

    // Header
    output += '[Script Info]\n';
    output += '; Generated by Dabbing Premium\n';
    output += 'Title: Dubbed Subtitles\n';
    output += 'ScriptType: v4.00+\n';
    output += 'WrapStyle: 0\n';
    output += 'PlayResX: 1920\n';
    output += 'PlayResY: 1080\n';
    output += 'ScaledBorderAndShadow: yes\n\n';

    // Styles
    output += '[V4+ Styles]\n';
    output += 'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, OutlineColour, BackColour, Bold, Italic, Underline, StrikeOut, ScaleX, ScaleY, Spacing, Angle, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, Encoding\n';
    output += 'Style: Default,Arial,48,&H00FFFFFF,&H000088EF,&H00000000,&H00666666,-1,0,0,0,100,100,0,0,1,2,1,2,10,10,10,1\n\n';

    // Events
    output += '[Events]\n';
    output += 'Format: Layer, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n';

    output += subtitles.map(sub => {
      const startTime = this.formatASSTimestamp(sub.startTime);
      const endTime = this.formatASSTimestamp(sub.endTime);
      const text = sub.text.replace(/\n/g, '\\N');

      return `Dialogue: 0,${startTime},${endTime},Default,,0,0,0,,${text}`;
    }).join('\n');

    return output;
  }

  /**
   * Convert to SSA format (similar to ASS but older)
   */
  toSSA(subtitles) {
    let output = '';

    // Header
    output += '[Script Info]\n';
    output += '; Generated by Dabbing Premium\n';
    output += 'Title: Dubbed Subtitles\n';
    output += 'ScriptType: v4.00\n\n';

    // Styles
    output += '[V4 Styles]\n';
    output += 'Format: Name, Fontname, Fontsize, PrimaryColour, SecondaryColour, TertiaryColour, BackColour, Bold, Italic, BorderStyle, Outline, Shadow, Alignment, MarginL, MarginR, MarginV, AlphaLevel, Encoding\n';
    output += 'Style: Default,Arial,48,16777215,65535,65535,0,-1,0,1,2,1,2,10,10,10,0,1\n\n';

    // Events
    output += '[Events]\n';
    output += 'Format: Marked, Start, End, Style, Name, MarginL, MarginR, MarginV, Effect, Text\n';

    output += subtitles.map(sub => {
      const startTime = this.formatASSTimestamp(sub.startTime);
      const endTime = this.formatASSTimestamp(sub.endTime);
      const text = sub.text.replace(/\n/g, '\\N');

      return `Dialogue: Marked=0,${startTime},${endTime},Default,,0,0,0,,${text}`;
    }).join('\n');

    return output;
  }

  /**
   * Convert to SUB format (MicroDVD)
   */
  toSUB(subtitles, fps = 25) {
    return subtitles.map(sub => {
      const startFrame = Math.round((sub.startTime / 1000) * fps);
      const endFrame = Math.round((sub.endTime / 1000) * fps);
      const text = sub.text.replace(/\n/g, '|'); // SUB uses | for line breaks

      return `{${startFrame}}{${endFrame}}${text}`;
    }).join('\n');
  }

  /**
   * Format timestamp for SRT (00:00:00,000)
   */
  formatSRTTimestamp(ms) {
    const hours = Math.floor(ms / 3600000);
    const minutes = Math.floor((ms % 3600000) / 60000);
    const seconds = Math.floor((ms % 60000) / 1000);
    const milliseconds = ms % 1000;

    return `${this.pad(hours, 2)}:${this.pad(minutes, 2)}:${this.pad(seconds, 2)},${this.pad(milliseconds, 3)}`;
  }

  /**
   * Format timestamp for VTT (00:00:00.000)
   */
  formatVTTTimestamp(ms) {
    const hours = Math.floor(ms / 3600000);
    const minutes = Math.floor((ms % 3600000) / 60000);
    const seconds = Math.floor((ms % 60000) / 1000);
    const milliseconds = ms % 1000;

    return `${this.pad(hours, 2)}:${this.pad(minutes, 2)}:${this.pad(seconds, 2)}.${this.pad(milliseconds, 3)}`;
  }

  /**
   * Format timestamp for ASS/SSA (0:00:00.00)
   */
  formatASSTimestamp(ms) {
    const hours = Math.floor(ms / 3600000);
    const minutes = Math.floor((ms % 3600000) / 60000);
    const seconds = Math.floor((ms % 60000) / 1000);
    const centiseconds = Math.floor((ms % 1000) / 10);

    return `${hours}:${this.pad(minutes, 2)}:${this.pad(seconds, 2)}.${this.pad(centiseconds, 2)}`;
  }

  /**
   * Pad number with zeros
   */
  pad(num, length) {
    return String(num).padStart(length, '0');
  }

  /**
   * Batch convert to multiple formats
   */
  convertToAll(subtitles) {
    const results = {};

    this.supportedFormats.forEach(format => {
      try {
        results[format] = this.convert(subtitles, format);
      } catch (error) {
        logError(`Failed to convert to ${format}`, { error: error.message });
        results[format] = null;
      }
    });

    return results;
  }

  /**
   * Download subtitle file
   */
  downloadAs(subtitles, format, filename = 'subtitles') {
    const content = this.convert(subtitles, format);
    const blob = new Blob([content], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    
    link.href = url;
    link.download = `${filename}.${format}`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    URL.revokeObjectURL(url);

    logInfo('Subtitle file downloaded', { format, filename });
  }

  /**
   * Get file extension for format
   */
  getExtension(format) {
    return format.toLowerCase();
  }

  /**
   * Get MIME type for format
   */
  getMimeType(format) {
    const mimeTypes = {
      srt: 'text/srt',
      vtt: 'text/vtt',
      ass: 'text/x-ssa',
      ssa: 'text/x-ssa',
      sub: 'text/x-microdvd'
    };

    return mimeTypes[format.toLowerCase()] || 'text/plain';
  }
}

// Export for both browser and Node.js
if (typeof module !== 'undefined' && module.exports) {
  module.exports = SubtitleConverter;
}
